package com.xyz.question_bank_management_system.modules.source.mapper;
import com.xyz.question_bank_management_system.modules.source.entity.*; import org.apache.ibatis.annotations.*; import java.util.List;
@Mapper public interface EvidenceLinkMapper { @Insert("INSERT INTO knowledge_source(knowledge_point_id,source_chunk_id,support_type,relevance_score,confidence,link_method,review_status,reviewed_by,created_at) VALUES(#{knowledgePointId},#{sourceChunkId},#{supportType},#{relevanceScore},#{confidence},#{linkMethod},#{reviewStatus},#{reviewedBy},NOW(3)) ON DUPLICATE KEY UPDATE support_type=VALUES(support_type),relevance_score=VALUES(relevance_score),confidence=VALUES(confidence),link_method=VALUES(link_method),review_status=VALUES(review_status),reviewed_by=VALUES(reviewed_by)") @Options(useGeneratedKeys=true,keyProperty="id") int upsertKnowledge(KnowledgeSource e); @Insert("INSERT INTO resource_source(resource_id,source_chunk_id,support_type,relevance_score,citation_order,created_at) VALUES(#{resourceId},#{sourceChunkId},#{supportType},#{relevanceScore},#{citationOrder},NOW(3)) ON DUPLICATE KEY UPDATE support_type=VALUES(support_type),relevance_score=VALUES(relevance_score),citation_order=VALUES(citation_order)") @Options(useGeneratedKeys=true,keyProperty="id") int upsertResource(ResourceSource e); @Select("SELECT * FROM knowledge_source WHERE knowledge_point_id=#{id} ORDER BY created_at DESC,id DESC") List<KnowledgeSource> byKnowledge(@Param("id") Long id); @Select("SELECT * FROM resource_source WHERE resource_id=#{id} ORDER BY citation_order,id") List<ResourceSource> byResource(@Param("id") Long id); }
